			if (val < 1) {
				shell_error(sh, "Invalid number of suite iterations");
				return -ENOEXEC;
			}
			suite_iter = val;
			opt_num++;
			break;
		case 'c':
			val = atoi(state->optarg);
			if (val < 1) {
				shell_error(sh, "Invalid number of case iterations");
				return -ENOEXEC;
